export function initCreatorFlow(){
 const root=document.querySelector('.customizer'),steps=[['Começo',['.format-field','#occasion-select','#wedding-path','#recipient','.experience-identity','#invite-fields']],['Fotos',['.photo-upload','#upload-status','.memory-photos','.memory-pages']],['Voz e música',['#message','.audio-studio','.letter-editor']],['Surpresas',['.extras-editor','.guest-manager','.reply-inbox']],['Visual',['.book-finish-editor','.appearance-editor','.stationery-editor','.story-design-editor','.character-field','.cover-field','.materials-panel','.qr-panel']],['Conferir',['.story-export-panel','.digital-delivery','.delivery-tools','#recipient-preview','.review-keepsake','.library-controls','.draft-status']]];
 root.querySelector('.atelier-steps').hidden=true;const nav=document.createElement('nav');nav.className='creator-flow-tabs';nav.setAttribute('aria-label','Etapas para criar seu presente');const heading=document.createElement('h3');heading.className='creator-flow-heading';const hint=document.createElement('p');hint.className='creator-flow-hint';hint.textContent='Faça no seu ritmo. Você pode voltar e mudar tudo.';const quick=document.createElement('div');quick.className='creator-format-switch';quick.setAttribute('role','group');quick.setAttribute('aria-label','Tipo de presente');for(const [key,label] of [['stories','Stories'],['livro','Livro com páginas'],['cartao','Cartão simples'],['convite','Convite 3D']]){const button=document.createElement('button');button.type='button';button.className='quick-format';button.dataset.quickFormat=key;button.textContent=label;button.addEventListener('click',()=>document.querySelector('.format[data-format='+key+']').click());quick.append(button);}root.prepend(nav,quick,heading,hint);let active=0;const panels=[];
 steps.forEach(([label,selectors],index)=>{const section=document.createElement('section');section.className='creator-flow-panel';section.id='creator-step-'+index;section.setAttribute('aria-label',label);for(const selector of selectors){let element=root.querySelector(selector);if(element?.matches('input,textarea,select'))element=element.closest('.field');if(element)section.append(element);}if(index===4){for(const element of [...section.children]){if(element.tagName==='DETAILS')continue;const fold=document.createElement('details');fold.className='creator-option-fold';if(element.classList.contains('appearance-editor'))fold.open=true;const summary=document.createElement('summary');summary.textContent=element.querySelector('h3,legend')?.textContent||({'qr-panel':'Cartão com QR','materials-panel':'Texturas e acabamentos'})[element.className]||'Mais detalhes';fold.append(summary);element.before(fold);fold.append(element);}}root.append(section);panels.push(section);const button=document.createElement('button');button.type='button';button.textContent=(index+1)+' '+label;button.setAttribute('aria-controls',section.id);button.addEventListener('click',()=>show(index));nav.append(button);});
 const controls=document.createElement('div');controls.className='creator-flow-controls';controls.innerHTML='<button type="button" class="creator-back">← Voltar</button><span role="status"></span><button type="button" class="creator-next">Continuar →</button>';root.append(controls);
 function show(index,scroll=true){active=Math.max(0,Math.min(steps.length-1,index));panels.forEach((panel,i)=>panel.hidden=i!==active);[...nav.children].forEach((button,i)=>{button.setAttribute('aria-current',i===active?'step':'false');button.classList.toggle('current',i===active);});heading.textContent=steps[active][0];controls.querySelector('.creator-back').disabled=active===0;controls.querySelector('.creator-next').hidden=active===steps.length-1;controls.querySelector('[role=status]').textContent=(active+1)+' de '+steps.length;if(scroll)root.scrollIntoView({behavior:'instant',block:'start'});}
 controls.querySelector('.creator-back').addEventListener('click',()=>show(active-1));controls.querySelector('.creator-next').addEventListener('click',()=>show(active+1));document.addEventListener('creator:reveal',event=>{const element=document.querySelector(event.detail);const index=panels.findIndex(panel=>panel.contains(element));if(index>=0){show(index,false);for(let parent=element?.parentElement;parent&&parent!==root;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;}});show(0,false);return {show};
}
